//! @file
//! @brief Carbonite carb_min/carb_max implementation
#pragma once

/**
 * Returns the smaller value. Returns the first argument when the arguments are equivalent.
 * \details Same as `std::min` but implemented without using the `min` keyword as Windows.h can sometimes `#define` it.
 * @param left The first value to compare.
 * @param right The second value to compare.
 * @returns \p left if \p left is less than \p right, otherwise \p right, even if the values are equal.
 */
template <class T>
[[nodiscard]] constexpr const T& carb_min(const T& left, const T& right) noexcept(noexcept(left < right))
{
    return right < left ? right : left;
}

/**
 * Returns the larger value. Returns the first argument when the arguments are equivalent.
 * \details Same as `std::max` but implemented without using the `max` keyword as Windows.h can sometimes `#define` it.
 * @param left The first value to compare.
 * @param right The second value to compare.
 * @returns \p right if \p left is less than \p right, otherwise \p left, even if the values are equal.
 */
template <class T>
[[nodiscard]] constexpr const T& carb_max(const T& left, const T& right) noexcept(noexcept(left < right))
{
    return left < right ? right : left;
}
